import json, pathlib
base = pathlib.Path.home()/ "workspace/divination/benchmark/phase3/runs/holdout17-acceptance/predictions"
base.mkdir(parents=True, exist_ok=True)
TRIG={"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}
def w(cid, text, basis, conf):
    obj={"case_id":cid,"prediction_text":text,"basis":basis,"confidence":conf,"trigger":dict(TRIG),"systems_used":["大六壬"]}
    (base/f"{cid}.json").write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding="utf-8")

w("BYZ-017","方向：一年运程平滞偏弱，先迷后稍利，无大起大落之进益。张老夫子这一年以守旧安静为宜：官申乘天后发于传中，主上半年有官面/文书牵缠与阴人暗助并见，事来得慢、消息反复；玄胎四孟隐伏，主旧事未分、新谋未形，不宜在年内强求迁转或大兴作。应期定年档：窗口为全年，以秋申月为转折主坐标——申官逢值之月牵缠最显，过了申月后渐归平稳；次级线：寅禄乘青龙临干，春季寅月有一段得禄得助的小顺，只到小顺量级，不作全年大吉。",
"六壬年占/终身尺度（LR-QY-3.1年档）。课名遥克蒿矢：四课无克、上神遥克日干，章二遥克总象力弱难任；玄胎（元胎）寅申巳亥四孟主隐匿未分。甲木寅月旺相、日干有根故不作败断，只降量级；官鬼申金寅月囚、乘天后，主官面牵缠量级有限。应期三路：逢值取申月为主坐标，逢冲（寅冲申）为备选舍之因冲官反激缠，出空无据（旬空未在转录中明列）舍之。盘面为线性转录、三传栏解析有限，细断降档。",0.52)
w("BYZ-023","方向：逃亡者已经走远、追寻难获，人物短期内寻不回。弹射进茹主日克神而势递进，逃者一步步向外递去，非伏匿近处之象；财未乘螣蛇、官申乘贵人、鬼酉乘玄武并见，主逃者携财物惊疑而走、行藏带玄武暗匿。方位以未申酉递进之势主西南至西一带（未申方为主）。应期定日档：窗口为本旬内，主坐标取申日——申为递进中段、官贵逢值之日只主得消息/见踪迹，不主拿获；人归无期，近段（旬内）无获，远段无新触发不另报，属一段终局、远段无据不报追获之期。",
"六壬失物走失/行人门（六节2/1）：类神行踪看三传递进与玄武行藏。课名遥克弹射兼进茹：弹射日遥克神、力弱，进茹递进主去势已成。乙木未月休、巳火泄，干弱去势难挽。应期三路：逢值申日取消息坐标，逢冲舍之（冲未财反主财散），出空无据舍之。线性转录三传以栏首财未、官申、鬼酉为据，方位细节降档。",0.55)
w("BYZ-028","方向：次子府试可取、能入选，喜中带迟，不是落榜之课。父母午火在午月午日两午并旺、乘青龙居传，文书试卷之神旺相得地，为试门最有力的一级据；但课名别责自在，别责总象罔济利守、三传取法迂回，主过程不顺、名次不居前列，属中下至中等入选而非案首高第。应期定月档：窗口为放榜之月，主坐标取榜月午日——父母午火逢值之日见榜上有名；近段考试本身平稳，远段榜名以此期落定，两段同向、远段触发即父母午火逢值。",
"六壬考试门（六节9考试细断）：取父母为文书卷。戊土以午火为父母，午月午时旺相乘青龙入传，一级据定可取主线；别责课（章二别责）只压过程与名次量级，不反转方向（LR-QY-3.4量级随据）。鬼寅乘螣蛇为次面：考前惊疑虚惊，无实据压卷面，降为背景。应期三路：逢值午日为主，逢冲子日舍之（冲父母反伤文书），出空无据舍之。",0.62)
w("BYZ-032","方向：祝姓家宅守静则安、动则多滞，今年不宜迁动兴作，宅内无大凶破败。伏吟天盘不动、兼玄胎隐伏，主家宅旧态凝住：事情停在原地、隐情不露，强行搬迁改造只会稽留生口舌。兄巳乘天空、财申乘玄武、父寅乘六合并见，主宅中有一段虚惊耗财与暗中失耗的小线，量级只到破小财、起口舌，不到败家。应期定月档：窗口为本季内，主坐标取申月——财申逢值之月耗财口舌最显，守静避过此月后宅气渐平；无远段翻转触发，作一段终局。",
"六壬家宅（DA-M15/M16家宅止就四课、支为宅）：丁火日支巳同位伏吟，伏吟任信宜静（章二伏吟、章三本格）。午月火旺、宅神不死绝故无大凶；兄乘天空主虚耗、财乘玄武主暗耗，二级据只定小耗次线（LR-QY-2.2）。应期三路：逢值申月为主，冲巳亥月舍之（伏吟忌冲动），出空无据舍之。线性转录据课名与三传栏首作断，细节降档。",0.58)
w("BYZ-037","方向：王东桥此病沉滞难愈，近段不危殆、远段转归不乐观，属久延重病、须防入秋后加重。近段：三传父丑、父戌、父未全是父母土神，稼穑土局凝滞，土重埋金，主脾胃壅滞、痰食积结、药食难行，病在中焦脾胃一线，势虽沉重而未见虎鬼绝命之组，近旬内以滞为主、无速愈之象。远段：伏吟静滞加三传纯土无子孙生气入传制化，远段触发为末传未土乘青龙却仍是父母埋金之神——救神不入传，待丑戌未土支逢值冲叠之期病势易进一层。应期定月档：窗口至秋前，主坐标取未月未日土气最旺之时为加重坐标；愈期无据不报，不以土局泛象给愈断。一段尺度内近远已分判，死断象组不全不迳断死。",
"六壬疾病门（六节5）：虎鬼/子孙生气为纲。本课三传纯父母（丑戌未）成稼穑，辛金日主被旺土所埋（未月土旺），子孙水、官鬼木皆不入传——生机一线无一级据，福德不临年命不作解厄（致死象组7b同旨）；但铸印、禄绝、马墓、子巳死字等致死组无一叠见，按分档只断重危久延、不迳断死（LR-QY-3.4）。伏吟主静滞。应期三路：逢值未支为主，逢冲丑冲未舍之（冲土反散而病根在埋金非土结），出空无据舍之。",0.6)
w("BYZ-046","方向：段梅臣之妻生产可顺，母子平安，产程稍迟而无产厄。子孙巳火在巳月旺相、乘六合居中传，胎神得地乘合将，是孕产门一级吉据；初传财辰乘勾陈主产前迟滞、勾连等待，末传官申乘贵人主终得贵助（医者/长辈得力）。男女：子孙巳火为阳支、巳月阳火当旺，阳曜主男，主断得男。应期定日档：窗口为本旬内，主坐标取亥日——冲动胎神巳支之日即产期（孕产门冲胎推产期）；近段待产迟滞、远段亥日冲胎而产，两段以冲胎为远段触发。",
"六壬孕产门（六节10）：子孙为胎，巳火子孙旺相乘六合入传定顺产主线；干损儿支伤母分判——干上、支上未见白虎鬼克子孙之组，母子安危同归平安。六仪兼伏吟只主迟滞（勾陈初传同向），不改顺产方向。应期三路：逢冲亥冲巳取冲胎为主坐标合门法，逢值巳日舍之（值胎主待而不动），出空无据舍之。",0.66)
w("BYZ-052","方向：自占妣墓得吉地，此墓可用、利后人，无凶咎需改迁。富贵兼三光吉格入课：用神旺相、吉神临用、日辰当令三光并见，又得富贵格，主墓地气场得位、安葬得宜。官亥乘贵人、子未乘太常、父卯乘勾陈并见，主墓事经官面/礼制无碍、祭祀衣食之奉可继。应期定年档：本题为墓地长久吉凶尺度，无近事应期可取，只以年档论其长效——安葬后当年内即见家门平稳，无须另择期改葬；若问下葬时日，取与三光同气的亥卯未合局逢值之月为宜月，主坐标亥月。",
"六壬家宅/坟墓门（DA-M16坟墓用天盘、第三节吉格）：三光、富贵为章三吉格，格吉且传将不克日，按课格节格吉传将无克则吉力实。丁火亥月虽休，但三光以日辰旺相当令为据已在格内成立，不以单月令降格。父母卯勾陈为坟墓土事正应，不作凶读。应期按LR-QY-3.3终身/长久尺度取年档，档外日坐标不取。",0.64)
w("CY-009","方向：代占刺史因荐劾一事，先有一番风波、终归和平，不至贬黜罢职，属有惊无险的官场波折。合局克干、命上乘螣蛇官鬼，主劾章/言辞先压其身、惊疑风波实有；但三传为天将所制，克干之势被制化，风波到头被压平，结局保住职位、至多申饬虚惊。应期定月档：窗口为两月内，主坐标取申月——四课申金官鬼逢值之月风波最盛、亦在此月内被制而平；近段（本月）风声紧，远段（次月后）归平，远段触发为三传制鬼之神逢值收束。",
"六壬仕宦/官讼门（六节9/4）：官鬼为劾责本体，乙木日主六月未月休囚，申酉金官入课克干定风波主线；制鬼有据（输入盘面三传天将制）则按父母化官/子孙制鬼同旨降为有惊无险，不作罢黜极端量级（LR-QY-3.4）。螣蛇乘鬼主虚惊扰攘（四节螣蛇）。应期三路：逢值申月为主，逢冲寅月舍之（冲官反激劾），出空：寅卯旬空与本案官线无涉舍之。输入无独立三传栏，以四课与盘列作断，置信降一档。",0.6)
w("CY-013","方向：本科状元落在两湖一带（湖广分野为主，广西为次选分野），姓氏主断陈姓，王姓为次选。具体落断：主坐标取湖南/湖北两湖之地、陈姓状元；若两湖不应，则退至广西、王姓，二者只取一主一备，不并作双主断。依据尺度为单次科榜事件，无应期日月可再细化，应期即本榜放榜之时（月档，以榜期为窗）。",
"六壬考试/选举门分野法（六节9）：以天罡辰加巳居巽宫分野断省——辰巳居东南巽位而辰为天罡临巳，对应湖广分野为正断；未土乘贵人临干，未与陈/王姓氏取象为输入盘面候选行所据之类象链（天罡加巳、贵人临干两据），按第八节细断降档处理：省分给一主一备、姓氏给一主一备，置信低。输入无独立三传栏，细断（省、姓）属事象级推断、直接支持有限，故confidence低报。",0.42)
w("CY-017","方向：此胎所产必男，产期在十月辰日，母体可安，但此子生后难育、须防夭损之虞。男女三路：日上辰土为甲木之财、干阳得阳支辰再见，四课辰午寅皆阳支递进，阳曜占胜，主男；产期以辰支重见逢值为坐标。难育一线：甲子日旬空戌亥，虽不直空胎位，然三传取象辰土财重、子水印位受辰午递进所泄，小儿生后根气不固，主难养难育，量级到难育而非断言必夭。应期定月档转日坐标：窗口十月内，主坐标辰日生产（孕产门以冲值胎位支取期，本盘辰重见取逢值）。近段妊娠安，远段产后难育，远段触发为产后子星无生扶之盘面结构。",
"六壬孕产门（六节10）男女三路合看：阳支递进与干阳主男一路占胜，另两路（阴神、三合局）输入无天将全列无法全核，明写以阳曜一路为主、三路不全降置信。母子分判（通则f）：母体支位无鬼虎克伤，主母安；难育只落子身。应期三路：逢值辰日为主，逢冲戌日舍之（戌落旬空，冲而无力），出空戌亥与产期无涉舍之。输入无独立三传栏，降置信。",0.55)
w("CY-023","方向：遣仆借银，事可允许氏、但有两个分段结果——近段仆人必空手而回，当下借不到手；远段其银后时方许送来，最终得银不过六数之量。近段：天财临空、驿马入墓，使者此行落空，空回无疑。远段：财爻乘贵人发用、青龙长生临干，债主口头/信约已允，待后时兑现，得数以六为限（六十或六百量级随其家资，只断六数）。应期定日档转旬窗：窗口为出旬后一旬内，主坐标取财神出空填实之日银至；近段空回在旬内，远段得银在出空之后，远段触发即天财出空填实。",
"六壬求财门（六节7）：财乘贵人发用加青龙长生临干为允借一级据；财临旬空、马入墓为使者空回一级据——两据并存按LR-QY-1.3分层：允否一层归成、到手时序一层归迟，不互相吞没。丁火日主九月戌月相气，财金有气可得。应期三路按第七节优先序：落空者先取出空填实为主坐标，逢值舍之（值而仍空不实），逢冲舍之（冲空已在填实路内合看）。输入无独立三传栏，以四课盘列作断。",0.63)
w("CY-027","方向：买舟赴省一路平安可达，无覆舟大险；途中唯一应事是主仆有人小疾一场，量级只到抱病不适，不到伤损致死。三传成合局递生日至、支神相生，为出行门平安之象，干支无七战齐临、无玄武劫煞克命之组，险量只在最低档之下；病符加行年一象单见，按出行险量分级只记防病一层。应期定日档：行期以马逢值即行、抵省在本程旬内，主坐标取抵省之日以合局末支逢值日计；小疾应在途中行年病符逢值之日，程度轻、过日即缓。一段终局：远段归程无盘面触发，不另报。",
"六壬出行门（六节8及险量分级）：合局生干、支相生定平安主线；致死组合四件（行入空墓、中传劫丁刑干支、末传子巳死字、河井发用）逐件核无，伤损档玄劫克命年无据，故量级封顶在平安加小疾（LR-QY-3.4）。戊土七月申月泄气而得合局生扶，不作弱断。应期三路：合处定来期（通法6）取末支逢值为主，逢冲舍之，出空辰巳空与行人干支无涉舍之。输入无独立三传栏，行年病符为盘面已给之象据此作次线。",0.62)
w("CY-030","方向：新任荆门州刺史可以到任，但先有阻隔稍留、后方起程，到任落在午月寅日。近段：发用虽主起程之象（斩关、龙合白虎入传），然发用逢生宜而乘勾陈，主起程前被案件公事勾留一段，不能即行。远段：末传白虎天马加临午位，马动逢值方真行，远段触发即天马午位逢值逢冲——午月寅日寅木冲动/引动行程而到任。应期定月档：窗口为午月一月内，主坐标取午月寅日到任；档外他月坐标不取。输入成色乙：一二课分位未确指、验语尾残，已按残损降置信，方向与主坐标只据可确指的三四课午申递进与马位午作断。",
"六壬仕宦/出行门到任（六节9迁期、六节8行期）：勾陈乘用主勾留迟滞（四节勾陈斗讼勾连），白虎天马主行程发动。壬水日主七月申月得生，官星土位居支辰为任地。旬空午未：午位落空，故午月内须待寅日冲实/引动方到——应期优先序落空先取出空填实一路：以寅日为冲动坐标，逢值午日舍之（值而仍空），合处无据舍之。输入残损三项照实记于此并降置信，不臆补一二课细节。",0.5)
w("DA-032","方向：叶助教家宅不安中带耗，守之可安、终不至败宅：近段宅中有惊扰口舌与耗财，远段归于官面平息而宅可久居。干支两上皆午火财乘螣蛇临干临支，财蛇临宅主宅中因财/火光虚惊、妇人惊扰之象先起；中传兄亥乘天空，兄弟虚耗、言不实之耗在中段；末传官辰乘天后临本命丙辰，终局以官辰归命，宅事最后落到官面文书/正名而定，宅不失。应期定月档：窗口为本季，主坐标取午月——午财逢值之月惊耗最显，避过后以辰月官星逢值收束。母/长辈线：父母不入传只作背景，不据以断长辈吉凶（LR-QY-2.2三级）。",
"六壬家宅门（六节通则、DA-M15阳宅看支）：支丑上午火、干癸上同午，干支同象主宅身同扰。癸水二月卯月休囚、午火相气，财势压身定耗线；兄亥天空为二级虚耗据；末官辰乘天后且与本命丙辰同支，指代链最近（LR-QY-1.3①）定终局归官定宅。三传午-亥-辰：财去生官、递向末传收束。应期三路：逢值午月为主，逢冲子月舍之（冲财蛇反惊宅），出空寅卯空与传神无涉舍之。",0.6)
w("DA-040","方向：郑三公所占坟地可用、属中上吉地，葬后利子孙而无速发大贵，只到家门兴旺、子孙得官面小进之量级。初传官戌乘青龙居首，官龙临墓地为得位之象；中传父申乘白虎，白虎临父位主金石山形与先茔丧葬正应，不作凶杀读；末传财午乘玄武，财归玄武主地利暗藏、进益来得隐而迟。本命辛亥，亥为壬水长生之位而不在传中，根气只作背景加分，不升格。应期定年档：坟地长效尺度，葬后以午年/午月财星逢值为见利主坐标，年内先安、午期见兴。防线：干上酉金财气被未土等耗，只记葬事花费不菲一条次线。",
"六壬坟墓门（DA-M16坟墓用天盘、DA-M15分途）：壬水正月寅月休，官戌土乘青龙入传首位一级据定可用主线；父申白虎在丧葬门为正应将（四节白虎主丧亡之事体而非必凶人），与官龙同向不翻转。财午玄武二级据定暗利次线（LR-QY-2.2）。应期按LR-QY-3.3长久尺度取年档，逢值午为坐标，冲墓、出空（辰巳空不涉传神）两路舍之并记明。",0.62)
w("DA-052","方向：伊秀才科试难中、本次落榜，官星落空是决定一线。初传官丑乘太常却坐子丑旬空，官星空亡发用主名位虚悬、斩首之空坏在开头，试门以官/父母定名次者，官空即无名；中传子卯乘太阴，子孙泄气主才思泄而不聚；末传财巳乘贵人，只主试后得贵人财物/馆地之遇，与功名分层，不反转落榜主线。父母文书不入传，仅二级背景：卷面纵有可观亦不足以补官空。应期定月档：榜期窗口为放榜之月，主坐标取榜日见无名；出空后丑官逢值只主下科再图，不作本榜翻案。近段应试平稳无场外之灾，终局一段落榜。",
"六壬考试门（六节9考试细断）：取官星与父母。癸水六月未月休，官丑土虽旺而旬空——按空亡分位初传空斩首、且LR-QY-2.3官星空加受月泄（未冲丑）成组，许作无名否决；父母不入传按LR-QY-2.2只降权作背景，不许以卷面补名。财巳贵人为独立次面（LR-QY-1.4分层）：主试后财遇，不吞主线。应期三路：榜期月档，逢值榜日为主，出空路舍作本榜坐标（出空在榜后），逢冲未冲丑已计入官弱不另作期。",0.66)
w("DA-058","方向：邓巡辖赴任不成、本任落空，须待出空后再图别调，近时强行赴任必虚行而返。初传官寅乘青龙却坐寅卯旬空、又与本命戊寅同支同空——官星即年命，空亡发用斩首，赴任之职虚悬无实，是仕宦门官空虚望的正格；中传财亥乘太常主途中资费衣食耗去，末传子申乘天后归于本支，终以退归收束。应期定月档：窗口以出空为界，主坐标取寅月/寅日出空填实之时方有新任消息，本任在空旬内断无成行之日。近段虚行耗费，远段出空后别图，远段触发即官寅出空逢值。",
"六壬仕宦门（六节9）：官鬼为职本体，寅官青龙本吉将，然旬空且四月巳月木休囚，吉将空则吉不中（四节总论）；年命寅与初传叠合，指代链最近权重最高（LR-QY-1.3①），官空即命空，量级许定赴任不成（官空+休囚+斩首三项成组，合LR-QY-2.3c）。应期优先序：落空先取出空填实为主，逢值（空旬内寅日）舍之，逢冲申冲寅舍之（冲空已并入填实路）。",0.7)
w("DA-109","方向：叶七秀才平生以文书子嗣立身、无官无财的清平命，一生不至困顿绝路、亦无富贵大起，晚景靠子孙而安。初传父丑乘天后，父母土神居首主一生靠文书/长辈荫庇起家；中末子子、子亥两子孙水神乘太阴玄武递见，子孙旺（冬月水旺）主子嗣为后半生之靠、亦主其人以技艺生财暗进；官鬼木、妻财火皆不入传，按缺传只降权不断绝：官面只作无据不报高位、财面只作不聚大财读，不许断言终身绝无一官半职之逢。应期定年档/年龄档：平生尺度以行年论，前半程父荫在丑子之年见应，后半程子孙之靠在亥子之年见应，主坐标取行年至亥子水旺之程为晚景安顿之期。",
"六壬终身门（DA-M17前程以行年为主、DA-M18死断门槛）：辛金十二月相、水旺，父土生金、子水泄秀，三传父-子-子递生链完整，一级据定清平有靠主线。官财缺传按LR-QY-2.1只降权、2.3不许存在性否决，故不断绝官绝财。死墓绝不见成组（DA-M18门槛），不作寿限死断。应期按LR-QY-3.3终身尺度取年档/行年到临路（通法5），日月坐标不取。",0.6)
w("DA-125","方向：白生之妾生产母子可安、顺产得子，产程中有一段惊滞而终无产厄。初传子亥乘太常，子孙胎神得太常安奉之将居首，亥水在秋月得金生扶，胎位有气；中末两见兄酉乘太阴，兄弟金重主产时阴滞、产门开得慢与产后阴血之调需时，量级只到迟滞，不到难产伤母。干庚支申同气、母位申酉金气虽重而无白虎官鬼克子之组，干损儿支伤母两线逐核皆无克伤据，母子同安。男女：胎神亥为阴支、乘太常阴将，阴象占胜，主断得女。应期定日档：窗口为本旬内，主坐标取巳日——巳冲亥胎，冲胎推产期即以巳日为产时主坐标。",
"六壬孕产门（六节10）：子孙为胎，亥子乘太常入传首位一级据定安产；鬼虎克子之组无据，不上推产厄（险量同旨）。母子分判（通则f）：干上酉、支上酉皆兄非鬼，母儿无克伤。男女三路阴神/阴将一路可据、余路盘面有限，主断女并降置信。应期三路：逢冲巳冲亥合冲胎门法为主，逢值亥日舍之（值胎主待产不发动），出空子丑空与胎位无涉舍之。妾本命戊子，子落旬空只记根气稍弱背景，不压胎神一级据。",0.58)
w("DA-128","方向：季官人子息一事分两层——亲生子息难冀，过房子息可成。亲生层：末传子孙子水乘天空又坐子丑旬空，子星空亡临末、刖足无果，亲生一路断难，不许以官财之吉翻转此层。过房层：中传财卯乘六合，卯与本命己卯同支，财合临命主过继之人选有着落、合就可成，所过之子以卯命/属兔或东房近亲一线为正选。初传官午乘贵人主过继手续得官面/族中贵长作主而正名。应期定月档：窗口为半年内，主坐标取卯月——财卯逢值、本命逢值之月过房落定；亲生层无应期可报，明写无据不报。",
"六壬孕产/子息门（六节10子孙为子息本体、第六节13一象分判同旨）：子孙空末按空亡分位刖足加乘天空虚诈，亲生否决据成组（空+末位+天空，合LR-QY-2.3c）；过房另立取用链：财卯六合临本命为一级指代据（LR-QY-1.3①），官午贵人作正名次据，两层分判不相吞（LR-QY-1.4）。应期三路：逢值卯月为主，逢冲酉月舍之（冲财合主散），出空子水一路只关亲生层、不作过房期。",0.64)

